// Các ví dụ minh họa về Big O

// O(1) - Thời gian hằng số (không phụ thuộc kích thước mảng)
function getFirst(arr) {
  return arr[0];
}

// O(log n) - Logarit: Tìm kiếm nhị phân (chia đôi tập tìm kiếm mỗi bước)
function binarySearch(arr, target) {
  let left = 0, right = arr.length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (arr[mid] === target) return mid;
    if (arr[mid] < target) left = mid + 1;
    else right = mid - 1;
  }
  return -1;
}

// O(n) - Tuyến tính: Duyệt qua mảng 1 lần
function findMax(arr) {
  let max = arr[0];
  for (const num of arr) {
    if (num > max) max = num;
  }
  return max;
}

// O(n log n) - Tuyến tính x Logarit: Merge Sort
function mergeSort(arr) {
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));
  return merge(left, right);
}

// O(n²) - Bậc hai: 2 vòng lặp lồng nhau (Bubble Sort)
function bubbleSort(arr) {
  for (let i = 0; i < arr.length; i++)
    for (let j = 0; j < arr.length - i - 1; j++)
      if (arr[j] > arr[j+1]) [arr[j], arr[j+1]] = [arr[j+1], arr[j]];
  return arr;
}

// 1. Two Pointers - Tìm cặp phần tử có tổng bằng target trên mảng đã sắp xếp
function twoSum(sorted, target) {
  let left = 0, right = sorted.length - 1;
  while (left < right) {
    const sum = sorted[left] + sorted[right];
    if (sum === target) return [left, right];
    if (sum < target) left++;
    else right--;
  }
  return [-1, -1];
}

// 2. Sliding Window - Tìm tổng mảng con lớn nhất có độ dài k
function maxSubarraySum(arr, k) {
  let windowSum = 0;
  for (let i = 0; i < k; i++) windowSum += arr[i];
  let maxSum = windowSum;
  for (let i = k; i < arr.length; i++) {
    windowSum += arr[i] - arr[i - k]; // Trượt cửa sổ sang phải
    maxSum = Math.max(maxSum, windowSum);
  }
  return maxSum;
}

// 3. Frequency Map - Đếm tần suất xuất hiện của ký tự
function mostFrequent(arr) {
  const freq = {};
  let maxCount = 0, result = null;
  for (const item of arr) {
    freq[item] = (freq[item] || 0) + 1;
    if (freq[item] > maxCount) {
      maxCount = freq[item];
      result = item;
    }
  }
  return result;
}

// 4. Prefix Sum - Mảng cộng dồn giúp truy vấn tổng đoạn [i..j] trong O(1)
function prefixSum(arr) {
  const prefix = [0];
  for (const num of arr) prefix.push(prefix.at(-1) + num);
  return (i, j) => prefix[j + 1] - prefix[i];
}

// 1. Bubble Sort - O(n²), ổn định: đổi chỗ cặp kề nhau, dừng sớm nếu một vòng không đổi gì
function bubbleSort(input) {
  const arr = [...input]; // không làm hỏng mảng gốc
  for (let i = 0; i < arr.length - 1; i++) {
    let daDoi = false;
    for (let j = 0; j < arr.length - 1 - i; j++) {
      if (arr[j] > arr[j + 1]) {
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
        daDoi = true;
      }
    }
    if (!daDoi) break; // mảng đã sắp xếp: O(n) trong trường hợp tốt nhất
  }
  return arr;
}

// 2. Selection Sort - O(n²), không ổn định: mỗi vòng chọn phần tử nhỏ nhất đưa lên đầu
function selectionSort(input) {
  const arr = [...input];
  for (let i = 0; i < arr.length - 1; i++) {
    let nhoNhat = i;
    for (let j = i + 1; j < arr.length; j++) if (arr[j] < arr[nhoNhat]) nhoNhat = j;
    if (nhoNhat !== i) [arr[i], arr[nhoNhat]] = [arr[nhoNhat], arr[i]];
  }
  return arr;
}

// 3. Insertion Sort - O(n²), ổn định, gần O(n) khi mảng gần như đã sắp xếp
function insertionSort(input) {
  const arr = [...input];
  for (let i = 1; i < arr.length; i++) {
    const hienTai = arr[i];
    let j = i - 1;
    while (j >= 0 && arr[j] > hienTai) {
      arr[j + 1] = arr[j]; // đẩy phần tử lớn hơn sang phải
      j--;
    }
    arr[j + 1] = hienTai;
  }
  return arr;
}

// 4. Shell Sort - Insertion Sort với khoảng cách gap giảm dần: n/2, n/4, ..., 1
function shellSort(input) {
  const arr = [...input];
  for (let gap = Math.floor(arr.length / 2); gap > 0; gap = Math.floor(gap / 2)) {
    for (let i = gap; i < arr.length; i++) {
      const hienTai = arr[i];
      let j = i;
      while (j >= gap && arr[j - gap] > hienTai) {
        arr[j] = arr[j - gap];
        j -= gap;
      }
      arr[j] = hienTai;
    }
  }
  return arr;
}

// Chạy thử
const mang = [29, 10, 14, 37, 13, 5, 88, 1];
console.log('Bubble   :', bubbleSort(mang));
console.log('Selection:', selectionSort(mang));
console.log('Insertion:', insertionSort(mang));
console.log('Shell    :', shellSort(mang));

