// 1. Merge Sort - luôn O(n log n), ổn định, tốn O(n) bộ nhớ
function mergeSort(arr) {
  if (arr.length <= 1) return arr;
  const giua = Math.floor(arr.length / 2);
  return tron(mergeSort(arr.slice(0, giua)), mergeSort(arr.slice(giua)));
}
function tron(trai, phai) {
  const kq = [];
  let i = 0, j = 0;
  while (i < trai.length && j < phai.length) {
    kq.push(trai[i] <= phai[j] ? trai[i++] : phai[j++]); // <= giữ thứ tự phần tử bằng nhau
  }
  return kq.concat(trai.slice(i), phai.slice(j));
}

// 2. Quick Sort tại chỗ (phân hoạch Lomuto, pivot ngẫu nhiên) - trung bình O(n log n)
function quickSort(arr, dau = 0, cuoi = arr.length - 1) {
  if (dau >= cuoi) return arr;
  const ngauNhien = dau + Math.floor(Math.random() * (cuoi - dau + 1));
  [arr[ngauNhien], arr[cuoi]] = [arr[cuoi], arr[ngauNhien]]; // đưa pivot về cuối
  const pivot = arr[cuoi];
  let i = dau; // arr[dau..i-1] luôn < pivot
  for (let j = dau; j < cuoi; j++) {
    if (arr[j] < pivot) { [arr[i], arr[j]] = [arr[j], arr[i]]; i++; }
  }
  [arr[i], arr[cuoi]] = [arr[cuoi], arr[i]]; // pivot về đúng chỗ
  quickSort(arr, dau, i - 1);
  quickSort(arr, i + 1, cuoi);
  return arr;
}

// 3. Heap Sort - luôn O(n log n), O(1) bộ nhớ
function heapSort(input) {
  const arr = [...input];
  const n = arr.length;
  // Vun đống: đẩy arr[i] xuống tới khi lớn hơn cả hai con (trong phạm vi kichThuoc)
  const vunDong = (i, kichThuoc) => {
    while (true) {
      const trai = 2 * i + 1, phai = 2 * i + 2;
      let lonNhat = i;
      if (trai < kichThuoc && arr[trai] > arr[lonNhat]) lonNhat = trai;
      if (phai < kichThuoc && arr[phai] > arr[lonNhat]) lonNhat = phai;
      if (lonNhat === i) return;
      [arr[i], arr[lonNhat]] = [arr[lonNhat], arr[i]];
      i = lonNhat;
    }
  };
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) vunDong(i, n); // dựng max-heap
  for (let cuoi = n - 1; cuoi > 0; cuoi--) {
    [arr[0], arr[cuoi]] = [arr[cuoi], arr[0]]; // phần tử lớn nhất về cuối
    vunDong(0, cuoi);
  }
  return arr;
}

// 4. Counting Sort - O(n + k) cho số nguyên không âm, giá trị lớn nhất nhỏ
function countingSort(arr) {
  if (arr.length === 0) return [];
  const dem = new Array(Math.max(...arr) + 1).fill(0);
  for (const x of arr) dem[x]++;
  const kq = [];
  dem.forEach((soLan, giaTri) => { for (let i = 0; i < soLan; i++) kq.push(giaTri); });
  return kq;
}

// 5. Radix Sort (LSD, cơ số 10) - sắp theo từng chữ số từ hàng đơn vị lên
function radixSort(input) {
  let arr = [...input];
  const lonNhat = Math.max(0, ...arr);
  for (let hang = 1; Math.floor(lonNhat / hang) > 0; hang *= 10) {
    const xo = Array.from({ length: 10 }, () => []);
    for (const x of arr) xo[Math.floor(x / hang) % 10].push(x); // giữ thứ tự -> ổn định
    arr = xo.flat();
  }
  return arr;
}

// 6. Bucket Sort - số thực trong [0, 1), phân bố đều
function bucketSort(arr, soXo = arr.length || 1) {
  const xo = Array.from({ length: soXo }, () => []);
  for (const x of arr) xo[Math.min(soXo - 1, Math.floor(x * soXo))].push(x);
  return xo.flatMap(x => x.sort((a, b) => a - b));
}

