// 1. Linear Search - O(n): dùng được cả với mảng chưa sắp xếp
function linearSearch(arr, x) {
  for (let i = 0; i < arr.length; i++) if (arr[i] === x) return i;
  return -1;
}

// 2. Binary Search - O(log n): mảng PHẢI đã sắp xếp. Khoảng đóng [trai, phai]
function binarySearch(arr, x) {
  let trai = 0, phai = arr.length - 1;
  while (trai <= phai) {
    const giua = trai + Math.floor((phai - trai) / 2);
    if (arr[giua] === x) return giua;
    if (arr[giua] < x) trai = giua + 1; // bỏ nửa trái
    else phai = giua - 1;               // bỏ nửa phải
  }
  return -1;
}

// 3. Lower bound: vị trí đầu tiên có giá trị >= x. Khoảng nửa mở [trai, phai)
function lowerBound(arr, x) {
  let trai = 0, phai = arr.length;
  while (trai < phai) {
    const giua = (trai + phai) >> 1;
    if (arr[giua] < x) trai = giua + 1;
    else phai = giua;
  }
  return trai;
}

// 4. Upper bound: vị trí đầu tiên có giá trị > x
function upperBound(arr, x) {
  let trai = 0, phai = arr.length;
  while (trai < phai) {
    const giua = (trai + phai) >> 1;
    if (arr[giua] <= x) trai = giua + 1;
    else phai = giua;
  }
  return trai;
}

// 5. Tìm kiếm nhị phân trên đáp án: sức chứa nhỏ nhất để chở hết hàng trong `ngay` ngày
function sucChuaNhoNhat(hang, ngay) {
  const choDuoc = cap => {
    let soNgay = 1, dangCho = 0;
    for (const w of hang) {
      if (dangCho + w > cap) { soNgay++; dangCho = 0; }
      dangCho += w;
    }
    return soNgay <= ngay;
  };
  let trai = Math.max(...hang), phai = hang.reduce((a, b) => a + b, 0);
  while (trai < phai) {
    const giua = (trai + phai) >> 1;
    if (choDuoc(giua)) phai = giua; // chở được -> thử sức chứa nhỏ hơn
    else trai = giua + 1;
  }
  return trai;
}

